import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose

def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame.")

    if 'value' not in df.columns:
        raise ValueError("'df' must contain a 'value' column.")

    if decomposition_model not in {'additive', 'multiplicative'}:
        raise ValueError("'decomposition_model' must be 'additive' or 'multiplicative'.")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError):
        raise ValueError("'freq' must be a valid frequency string.")

    if df.empty:
        raise ValueError("'df' must not be empty.")

    values = pd.to_numeric(df['value'], errors='coerce')
    if values.isna().any():
        raise ValueError("'value' column must contain only valid numeric data.")

    if decomposition_model == 'multiplicative' and (values <= 0).any():
        raise ValueError("Multiplicative decomposition requires all values to be positive.")

    data = df.copy()

    if isinstance(data.index, (pd.DatetimeIndex, pd.PeriodIndex)):
        series = pd.Series(values.to_numpy(), index=data.index, name='value')
    elif 'date' in data.columns:
        dates = pd.to_datetime(data['date'], errors='coerce')
        if dates.isna().any():
            raise ValueError("'date' column must contain valid datetime values.")
        series = pd.Series(values.to_numpy(), index=pd.DatetimeIndex(dates), name='value')
    else:
        raise ValueError("'df' must have a DatetimeIndex, PeriodIndex, or a valid 'date' column.")

    series = series.sort_index()

    try:
        series = series.asfreq(freq)
    except ValueError:
        raise ValueError("'freq' must be a valid frequency string.")

    if series.isna().any():
        series = series.interpolate(method='time').ffill().bfill()

    try:
        period = max(2, int(round(pd.Timedelta(offset).total_seconds() / pd.Timedelta(offset).total_seconds())))
    except (TypeError, ValueError):
        period = None

    try:
        result = seasonal_decompose(
            series,
            model=decomposition_model,
            period=period,
            extrapolate_trend='freq'
        )
    except Exception as exc:
        raise ValueError(f"Could not decompose the time series: {exc}")

    fig = result.plot()
    ax = fig.axes[0] if fig.axes else plt.gca()

    return result, ax

